// Derived from Spacedrive (drive/apps/tauri/src-tauri/build.rs and crates/*/build.rs), adopted as
// the Aphrody Drive file explorer.
//! Tauri plugin build hook: generates one `allow-*` / `deny-*` permission per command (under
//! `permissions/autogenerated`) and, on macOS, links the Swift bridges (drag and drop, titlebar,
//! share sheet, "Open with").

/// Every command the plugin registers; keep in sync with `generate_handler!` in `src/lib.rs`.
const COMMANDS: &[&str] = &[
    "open_drive",
    "app_ready",
    "get_daemon_socket",
    "get_server_url",
    "get_current_library_id",
    "set_current_library_id",
    "get_selected_file_ids",
    "set_selected_file_ids",
    "daemon_request",
    "subscribe_to_events",
    "unsubscribe_from_events",
    "get_daemon_status",
    "start_daemon_process",
    "stop_daemon_process",
    "check_daemon_installed",
    "install_daemon_service",
    "uninstall_daemon_service",
    "open_macos_settings",
    "begin_drag",
    "end_drag",
    "get_drag_session",
    "force_clear_drag_state",
    "reveal_file",
    "share_files",
    "get_sidecar_path",
    "get_apps_for_paths",
    "open_path_default",
    "open_path_with_app",
    "open_paths_with_app",
    "register_keybind",
    "unregister_keybind",
    "get_registered_keybinds",
];

fn main() {
    // The daemon lookup also tries the Tauri `externalBin` name, suffixed with the target triple.
    if let Ok(target) = std::env::var("TARGET") {
        println!("cargo:rustc-env=APHRODY_DRIVE_TARGET={target}");
    }

    #[cfg(target_os = "macos")]
    {
        let deployment_target =
            std::env::var("MACOSX_DEPLOYMENT_TARGET").unwrap_or_else(|_| String::from("11.0"));
        swift_rs::SwiftLinker::new(deployment_target.as_str())
            .with_package("aphrody-drive-macos", "./macos/desktop")
            .with_package("FileOpening", "./macos/file-opening")
            .link();
    }

    tauri_plugin::Builder::new(COMMANDS).build();
}
